import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.security.*;
import java.util.Base64;

public class PaymentGateway {
    private static final Logger logger = Logger.getLogger(PaymentGateway.class.getName());
    private static final int MAX_RETRIES = 3;
    private static final long RETRY_DELAY_MS = 1000;
    private static final int RATE_LIMIT_PER_MINUTE = 60;

    private final AtomicInteger requestCount = new AtomicInteger(0);
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final ConcurrentHashMap<String, Long> rateLimitMap = new ConcurrentHashMap<>();
    private final SecretKey hmacKey;

    public PaymentGateway(byte[] keyMaterial) throws Exception {
        this.hmacKey = new SecretKeySpec(keyMaterial, "HmacSHA256");
        scheduler.scheduleAtFixedRate(() -> requestCount.set(0), 1, 1, TimeUnit.MINUTES);
    }

    public static class PaymentRequest {
        private final String merchantId;
        private final String transactionId;
        private final double amount;
        private final String currency;
        private final String customerRef;

        public PaymentRequest(String merchantId, String transactionId, double amount, String currency, String customerRef) {
            this.merchantId = merchantId;
            this.transactionId = transactionId;
            this.amount = amount;
            this.currency = currency;
            this.customerRef = customerRef;
        }

        public String getMerchantId() { return merchantId; }
        public String getTransactionId() { return transactionId; }
        public double getAmount() { return amount; }
        public String getCurrency() { return currency; }
        public String getCustomerRef() { return customerRef; }
    }

    public static class PaymentResponse {
        private final boolean success;
        private final String responseCode;
        private final String message;

        public PaymentResponse(boolean success, String responseCode, String message) {
            this.success = success;
            this.responseCode = responseCode;
            this.message = message;
        }

        public boolean isSuccess() { return success; }
        public String getResponseCode() { return responseCode; }
        public String getMessage() { return message; }
    }

    private boolean checkRateLimit(String merchantId) {
        if (requestCount.incrementAndGet() > RATE_LIMIT_PER_MINUTE) {
            return false;
        }
        Long lastRequest = rateLimitMap.get(merchantId);
        long now = System.currentTimeMillis();
        if (lastRequest != null && (now - lastRequest) < 100) {
            return false;
        }
        rateLimitMap.put(merchantId, now);
        return true;
    }

    private String computeHmac(String data) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(hmacKey);
        byte[] rawHmac = mac.doFinal(data.getBytes(StandardCharsets.UTF_8));
        return Base64.getEncoder().encodeToString(rawHmac);
    }

    private String sanitizeForLog(String input) {
        if (input == null) return "";
        return input.replaceAll("[^a-zA-Z0-9_\\-@.]", "_");
    }

    private String encodeHeaderValue(String value) {
        if (value == null) return "";
        // Encode for safe header inclusion - allow printable ASCII only
        StringBuilder sb = new StringBuilder();
        for (char c : value.toCharArray()) {
            if (c >= 0x20 && c <= 0x7E) {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    private String buildTransactionPayload(PaymentRequest request) {
        return String.format("%s|%s|%.2f|%s",
            request.getMerchantId(),
            request.getTransactionId(),
            request.getAmount(),
            request.getCurrency());
    }

    public PaymentResponse processPayment(PaymentRequest request) throws Exception {
        if (request == null) {
            throw new IllegalArgumentException("Payment request cannot be null");
        }

        String sanitizedMerchant = sanitizeForLog(request.getMerchantId());
        logger.info("Processing payment for merchant: " + sanitizedMerchant);

        if (!checkRateLimit(request.getMerchantId())) {
            logger.warning("Rate limit exceeded for: " + sanitizedMerchant);
            return new PaymentResponse(false, "429", "Rate limit exceeded");
        }

        return executeWithRetry(request, 0);
    }

    private PaymentResponse executeWithRetry(PaymentRequest request, int attempt) throws Exception {
        if (attempt >= MAX_RETRIES) {
            return new PaymentResponse(false, "503", "Service unavailable after retries");
        }

        try {
            return sendToProcessor(request);
        } catch (IOException e) {
            logger.warning("Attempt " + (attempt + 1) + " failed: " + e.getMessage());
            Thread.sleep(RETRY_DELAY_MS * (attempt + 1));
            return executeWithRetry(request, attempt + 1);
        }
    }

    private PaymentResponse sendToProcessor(PaymentRequest request) throws Exception {
        String payload = buildTransactionPayload(request);
        String signature = computeHmac(payload);

        URL url = new URL("https://processor.internal/api/v2/charge");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setDoOutput(true);
        conn.setConnectTimeout(5000);
        conn.setReadTimeout(10000);

        conn.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");
        conn.setRequestProperty("X-Signature", signature);
        conn.setRequestProperty("X-Merchant-Id", encodeHeaderValue(request.getMerchantId()));
        conn.setRequestProperty("X-Transaction-Id", encodeHeaderValue(request.getTransactionId()));

        // Customer reference is passed through for reconciliation
        String custRef = request.getCustomerRef();
        conn.setRequestProperty("X-Customer-Ref", encodeHeaderValue(custRef));

        // Build form body with amount details
        String body = buildRequestBody(request, signature);

        try (OutputStream os = conn.getOutputStream()) {
            os.write(body.getBytes(StandardCharsets.UTF_8));
        }

        int responseCode = conn.getResponseCode();
        if (responseCode == 200) {
            return new PaymentResponse(true, "200", "Payment processed");
        } else if (responseCode == 429) {
            throw new IOException("Upstream rate limited");
        } else {
            return new PaymentResponse(false, String.valueOf(responseCode), "Payment failed");
        }
    }

    private String buildRequestBody(PaymentRequest request, String signature) {
        StringBuilder body = new StringBuilder();
        body.append("merchant_id=").append(URLEncoder.encode(request.getMerchantId(), StandardCharsets.UTF_8));
        body.append("&transaction_id=").append(URLEncoder.encode(request.getTransactionId(), StandardCharsets.UTF_8));
        body.append("&amount=").append(String.format("%.2f", request.getAmount()));
        body.append("&currency=").append(URLEncoder.encode(request.getCurrency(), StandardCharsets.UTF_8));
        body.append("&customer_ref=").append(URLEncoder.encode(request.getCustomerRef(), StandardCharsets.UTF_8));
        body.append("&sig=").append(URLEncoder.encode(signature, StandardCharsets.UTF_8));
        return body.toString();
    }

    // Audit trail writer for compliance - writes to structured log file
    public void writeAuditRecord(PaymentRequest request, PaymentResponse response) throws IOException {
        String auditLine = formatAuditEntry(request, response);
        try (FileWriter fw = new FileWriter("/var/log/payments/audit.log", true);
             BufferedWriter bw = new BufferedWriter(fw)) {
            bw.write(auditLine);
            bw.newLine();
        }
    }

    private String formatAuditEntry(PaymentRequest request, PaymentResponse response) {
        long timestamp = System.currentTimeMillis();
        // Sanitize all fields for log safety
        String merchant = sanitizeForLog(request.getMerchantId());
        String txnId = sanitizeForLog(request.getTransactionId());
        String custRef = sanitizeForLog(request.getCustomerRef());
        String respCode = response.getResponseCode();

        return String.format("%d|%s|%s|%.2f|%s|%s|%s",
            timestamp, merchant, txnId, request.getAmount(),
            request.getCurrency(), custRef, respCode);
    }

    // Validates a merchant-supplied callback URL to prevent SSRF (CWE-918).
    // Only permits https and rejects loopback/link-local/private/internal hosts.
    private void validateCallbackUrl(URL url) throws IOException {
        String protocol = url.getProtocol();
        if (protocol == null || !protocol.equalsIgnoreCase("https")) {
            throw new IOException("Callback URL must use https");
        }
        String host = url.getHost();
        if (host == null || host.isEmpty()) {
            throw new IOException("Callback URL host is missing");
        }
        try {
            for (InetAddress addr : InetAddress.getAllByName(host)) {
                if (addr.isAnyLocalAddress() || addr.isLoopbackAddress()
                        || addr.isLinkLocalAddress() || addr.isSiteLocalAddress()
                        || addr.isMulticastAddress()) {
                    throw new IOException("Callback URL resolves to a disallowed address");
                }
            }
        } catch (UnknownHostException e) {
            throw new IOException("Callback URL host could not be resolved", e);
        }
    }

    // Webhook notification to merchant callback URL
    public void notifyMerchant(String callbackUrl, PaymentRequest request, PaymentResponse response) throws Exception {
        URL url = new URL(callbackUrl);
        validateCallbackUrl(url);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setInstanceFollowRedirects(false);
        conn.setRequestMethod("POST");
        conn.setDoOutput(true);
        conn.setConnectTimeout(3000);
        conn.setReadTimeout(5000);

        conn.setRequestProperty("Content-Type", "application/json");
        String notifSignature = computeHmac(request.getTransactionId() + "|" + response.getResponseCode());
        conn.setRequestProperty("X-Webhook-Signature", notifSignature);

        // Include original customer reference in notification header for correlation
        String headerSafeRef = toHeaderSafe(request.getCustomerRef());
        conn.setRequestProperty("X-Correlation-Ref", headerSafeRef);

        String jsonBody = String.format(
            "{\"transaction_id\":\"%s\",\"status\":\"%s\",\"amount\":%.2f}",
            escapeJson(request.getTransactionId()),
            escapeJson(response.getResponseCode()),
            request.getAmount());

        try (OutputStream os = conn.getOutputStream()) {
            os.write(jsonBody.getBytes(StandardCharsets.UTF_8));
        }
        conn.getResponseCode(); // consume response
        conn.disconnect();
    }

    private String toHeaderSafe(String value) {
        if (value == null) return "";
        // Remove null bytes and limit length
        String cleaned = value.replace("\0", "");
        if (cleaned.length() > 128) {
            cleaned = cleaned.substring(0, 128);
        }
        // Strictly filter to visible ASCII printable characters only
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < cleaned.length(); i++) {
            char c = cleaned.charAt(i);
            if (c >= 0x20 && c <= 0x7E) {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r");
    }
}
